# Admin — full access for operational tooling and Sentinel.
# Retains CONFIG, SHUTDOWN (these are renamed to empty strings in
# redis.conf so the ACL grants are effectively no-ops). The admin
# user's +@all grants access to all non-renamed commands.
user admin on ~* > {{REDIS_ADMIN_PASSWORD}} &
* +@all

# App — application service account (API, Dashboard workers).
# All commands except dangerous category (FLUSH*, DEBUG, CONFIG, SHUTDOWN, etc.).
user app on ~* > {{REDIS_PASSWORD}} &
* +@all -@dangerous

# Readonly — read replicas / monitoring / health checks.
# Only @read category commands.
user readonly on ~* > {{REDIS_READONLY_PASSWORD}} &
* +@read

# Sentinel — used by Sentinel instances to connect to Redis nodes.
# 2.7 Fix: Scoped to only commands Sentinel actually needs.
user sentinel on ~* > {{REDIS_SENTINEL_PASSWORD}} &
* +ping +sentinel | * +subscribe +publish
